405	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
406	            StringBuilder sb = new StringBuilder(digest.length * 2);
407	            for (byte b : digest) {
408	                sb.append(String.format("%02x", b));
409	            }
410	            return sb.toString();
411	        } catch (NoSuchAlgorithmException ex) {
412	            throw new IllegalStateException("SHA-256 not available", ex);
413	        }
414	    }
