416	    /**
417	     * Rejects a create whose derived identity collides with an existing owner's, reported via
418	     * {@link DuplicateTelephoneException} which the handler translates to a 409. Duplicate detection
419	     * is now the single identity key: the new owner's {@link #identityKeyFor identityKey} (the
420	     * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
421	     * compared against each existing owner's, ignoring owners flagged deleted. The email-domain
422	     * block list has already been applied while normalizing the email, so it takes effect first. An
423	     * existing telephone that cannot form a valid E.164 number is skipped rather than colliding.
424	     * Because the telephone is part of the key, two owners with the same surname and postcode but
425	     * different telephones no longer collide here - they are surfaced as a soft match instead. The
426	     * former separate telephone, email and household 409 blocks are all subsumed by this key.
427	     */
428	    private void rejectDuplicateIdentity(String normalizedTelephone, String normalizedEmail, String lastName) {
429	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
430	        for (Owner existing : this.clinicService.findAllOwners()) {
431	            if (existing.isDeleted()) {
432	                continue;
433	            }
434	            String existingTelephone;
435	            try {
436	                existingTelephone = normalizeTelephone(existing.getTelephone());
437	            } catch (InvalidTelephoneException ex) {
438	                continue;
439	            }
440	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
441	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
442	            if (identityKey.equals(existingKey)) {
443	                throw new DuplicateTelephoneException(normalizedTelephone);
444	            }
445	        }
446	    }
