448	    /**
449	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
450	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
451	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
452	     * spacing do not defeat the duplicate-household check.
453	     */
454	    private static String collapse(String value) {
455	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
456	    }
