458	    /**
459	     * Normalizes an owner's address into a canonical form applied on every create: leading and
460	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
461	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
462	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
463	     * and returned, and is the form every address comparison (duplicate-household detection and the
464	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
465	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
466	     * so normalizing an already-normalized address is a no-op.
467	     */
468	    private static String normalizeAddress(String address) {
469	        if (address == null) {
470	            return "";
471	        }
472	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
473	        if (collapsed.isEmpty()) {
474	            return "";
475	        }
476	        String[] tokens = collapsed.split(" ");
477	        StringBuilder sb = new StringBuilder(collapsed.length());
478	        for (int i = 0; i < tokens.length; i++) {
479	            String token = tokens[i];
480	            switch (token) {
481	                case "ST" -> token = "STREET";
482	                case "RD" -> token = "ROAD";
483	                case "AVE" -> token = "AVENUE";
484	                default -> {
485	                }
486	            }
487	            if (i > 0) {
488	                sb.append(' ');
489	            }
490	            sb.append(token);
491	        }
492	        return sb.toString();
493	    }
