495	    /**
496	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
497	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
498	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
499	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
500	     * region derivation shared by the {@code memberId} and the owner's locality.
501	     */
502	    private static String deriveRegion(String city, String postcode) {
503	        if (postcode != null) {
504	            try {
505	                int pc = Integer.parseInt(postcode.trim());
506	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
507	                    int[] bounds = range.getValue();
508	                    if (pc >= bounds[0] && pc <= bounds[1]) {
509	                        return range.getKey();
510	                    }
511	                }
512	            } catch (NumberFormatException ignored) {
513	                // not a numeric postcode; fall back to the city-to-region table
514	            }
515	        }
516	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
517	    }
