519	    /**
520	     * Builds the {@code memberId} for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
521	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
522	     * city), {@code FY} is the 2-digit fiscal year of the {@code registrationDate} (matching the owner's
523	     * {@code fiscalYear}), {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
524	     * {@code normalizedTelephone + lastName} (the same HASH8 used by the region-and-hash identity), and
525	     * {@code CHK} is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}
526	     * (e.g. {@code 'NSW271A2B3C4D5'}). This is a stable identity: it carries no sequence number and
527	     * depends only on the owner's own region, fiscal year, telephone and surname.
528	     */
529	    private static String memberIdFor(String region, LocalDate registrationDate,
530	                                      String normalizedTelephone, String lastName) {
531	        String fy = String.format("%02d", fiscalYearOf(registrationDate) % 100);
532	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
533	        String base = region + fy + hash8;
534	        return base + luhnCheckDigit(base);
535	    }
