537	    /**
538	     * The single Luhn check digit (0-9) computed over the digits contained in {@code value};
539	     * non-digit characters are ignored.
540	     */
541	    private static int luhnCheckDigit(String value) {
542	        int sum = 0;
543	        boolean dbl = true;
544	        for (int i = value.length() - 1; i >= 0; i--) {
545	            char c = value.charAt(i);
546	            if (c < '0' || c > '9') {
547	                continue;
548	            }
549	            int d = c - '0';
550	            if (dbl) {
551	                d *= 2;
552	                if (d > 9) {
553	                    d -= 9;
554	                }
555	            }
556	            sum += d;
557	            dbl = !dbl;
558	        }
559	        return (10 - (sum % 10)) % 10;
560	    }
