562	    /**
563	     * De-duplicates a freshly computed {@code memberId} against the ids already carried by existing
564	     * owners. When the base id is unused it is returned unchanged; otherwise {@code '-<n>'} is appended
565	     * with the smallest {@code n} of 2 or more that yields an id no existing owner already holds. The
566	     * count reflects the state prior to this create.
567	     */
568	    private String deduplicateMemberId(String baseId) {
569	        Set<String> existingIds = new HashSet<>();
570	        for (Owner existing : this.clinicService.findAllOwners()) {
571	            String id = existing.getMemberId();
572	            if (id != null) {
573	                existingIds.add(id);
574	            }
575	        }
576	        if (!existingIds.contains(baseId)) {
577	            return baseId;
578	        }
579	        int n = 2;
580	        while (existingIds.contains(baseId + "-" + n)) {
581	            n++;
582	        }
583	        return baseId + "-" + n;
584	    }
