586	    /**
587	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
588	     * bytes of {@code value}.
589	     */
590	    private static String sha256HexPrefix(String value, int hexChars) {
591	        try {
592	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
593	            StringBuilder sb = new StringBuilder(hexChars);
594	            for (byte b : digest) {
595	                if (sb.length() >= hexChars) {
596	                    break;
597	                }
598	                sb.append(String.format("%02X", b));
599	            }
600	            return sb.substring(0, hexChars);
601	        } catch (NoSuchAlgorithmException ex) {
602	            throw new IllegalStateException("SHA-256 not available", ex);
603	        }
604	    }
