616	    /**
617	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
618	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
619	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
620	     * it is a pure function of that pair, every owner in the same household - whether created first
621	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
622	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
623	     * segment.
624	     */
625	    private static String householdIdFor(String lastName, String postcode) {
626	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
627	        try {
628	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
629	            StringBuilder sb = new StringBuilder(12);
630	            for (byte b : digest) {
631	                if (sb.length() >= 12) {
632	                    break;
633	                }
634	                sb.append(String.format("%02x", b));
635	            }
636	            return sb.substring(0, 12);
637	        } catch (NoSuchAlgorithmException ex) {
638	            throw new IllegalStateException("SHA-256 not available", ex);
639	        }
640	    }
