643	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
644	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
645	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
646	     */
647	    private int countNamesakes(String firstName, String lastName) {
648	        int count = 0;
649	        for (Owner existing : this.clinicService.findAllOwners()) {
650	            if (firstName.equalsIgnoreCase(existing.getFirstName())
651	                && lastName.equalsIgnoreCase(existing.getLastName())) {
652	                count++;
