659	     * Counts the members of the household the new owner will belong to, as it stands after this
660	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
661	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
662	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
663	     * stored on the owner as its {@code householdMemberCount}.
664	     */
665	    private int countHouseholdMembers(String householdId) {
666	        int count = 1;
667	        for (Owner existing : this.clinicService.findAllOwners()) {
668	            if (householdId.equals(existing.getHouseholdId())) {
669	                count++;
670	            }
671	        }
