675	    /**
676	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
677	     * that is not a hard identity collision but whose {@code lastName} has the same
678	     * {@link #soundex soundex} code as the new owner's and whose {@code postcode} matches, while its
679	     * {@link #identityKeyFor identityKey} differs. The new owner's postcode must be present for a
680	     * soft match to be possible. When several existing owners qualify the one with the lowest id is
681	     * chosen. Returns the matching owner's id, or {@code null} when there is no soft match. This is
682	     * evaluated after the hard-duplicate check has already passed, so any surviving owner sharing the
683	     * surname's soundex and postcode necessarily has a different identity key (typically a different
684	     * telephone). A caller that declares {@code sharesHousehold} is deliberately joining an existing
685	     * household, so it is not flagged as a suspected duplicate.
686	     */
687	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
688	                                            String normalizedEmail) {
689	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
690	            return null;
691	        }
692	        String postcode = ownerFieldsDto.getPostcode();
693	        if (postcode == null) {
694	            return null;
695	        }
696	        String lastName = ownerFieldsDto.getLastName();
697	        if (lastName == null) {
698	            return null;
699	        }
700	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
701	        String soundex = soundex(lastName);
702	        Integer matchId = null;
703	        for (Owner existing : this.clinicService.findAllOwners()) {
704	            if (existing.isDeleted()) {
705	                continue;
706	            }
707	            if (!soundex.equals(soundex(existing.getLastName()))) {
708	                continue;
709	            }
710	            if (!postcode.equals(existing.getPostcode())) {
711	                continue;
712	            }
713	            String existingTelephone;
714	            try {
715	                existingTelephone = normalizeTelephone(existing.getTelephone());
716	            } catch (InvalidTelephoneException ex) {
717	                continue;
718	            }
719	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
720	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
721	            if (identityKey.equals(existingKey)) {
722	                continue;
723	            }
724	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
725	                matchId = existing.getId();
726	            }
727	        }
728	        return matchId;
729	    }
