731	    /**
732	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
733	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
734	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
735	     * points on create.
736	     */
737	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
738	
739	    /**
740	     * The household size (number of members) at or above which an owner earns the household points.
741	     */
742	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
743	
744	    /**
745	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
746	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
747	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
748	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
749	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
750	     * the tenure points never apply on create.
751	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
752	     * have been set.
753	     */
754	    private static int membershipPointsFor(Owner owner) {
755	        int points = 0;
756	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
757	            points += 2;
758	        }
759	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
760	            points += 1;
761	        }
762	        if (owner.getHouseholdMemberCount() != null
763	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
764	            points += 2;
765	        }
766	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
767	            points += 3;
768	        }
769	        return points;
770	    }
