772	    /**
773	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
774	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
775	     */
776	    private static int membershipLevelForPoints(int points) {
777	        if (points <= 1) {
778	            return 1;
779	        }
780	        if (points <= 3) {
781	            return 2;
782	        }
783	        if (points <= 5) {
784	            return 3;
785	        }
786	        return 4;
787	    }
