789	    /**
790	     * Caps a newly computed {@code membershipLevel} so it never exceeds one above the current maximum
791	     * {@code membershipLevel} among the new owner's household members - the existing, non-deleted
792	     * owners already carrying the same {@code householdId}. When the household has no existing member
793	     * (or none with a recorded level) no cap applies and the level is returned unchanged; otherwise the
794	     * level is limited to {@code max(member level) + 1}. The count reflects the state prior to this
795	     * create, as the new owner has not yet been saved.
796	     */
797	    private int capMembershipLevelByHousehold(int membershipLevel, String householdId) {
798	        Integer maxMemberLevel = null;
799	        for (Owner existing : this.clinicService.findAllOwners()) {
800	            if (existing.isDeleted()) {
801	                continue;
802	            }
803	            if (!householdId.equals(existing.getHouseholdId())) {
804	                continue;
805	            }
806	            Integer existingLevel = existing.getMembershipLevel();
807	            if (existingLevel == null) {
808	                continue;
809	            }
810	            if (maxMemberLevel == null || existingLevel > maxMemberLevel) {
811	                maxMemberLevel = existingLevel;
812	            }
813	        }
814	        if (maxMemberLevel == null) {
815	            return membershipLevel;
816	        }
817	        return Math.min(membershipLevel, maxMemberLevel + 1);
818	    }
