820	    /**
821	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
822	     * crossed between its {@code registrationDate} and the current server date. An owner with no
823	     * registration date, or one dated in the future, has a tenure of zero.
824	     */
825	    private static long tenureInFiscalYears(Owner owner) {
826	        LocalDate registrationDate = owner.getRegistrationDate();
827	        if (registrationDate == null) {
828	            return 0;
829	        }
830	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
831	    }
