932	    /**
933	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
934	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
935	     * unchanged. This is applied to the effective registration date - whether supplied in the request
936	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
937	     * from it, always falls on a business day.
938	     */
939	    /**
940	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
941	     * only ever explicitly supplied on the request; when present it must not be later than the
942	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
943	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
944	     * later from the server date) is accepted.
945	     */
946	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
947	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
948	            throw new FutureRegistrationDateException(registrationDate);
949	        }
950	    }
951	
952	    /**
953	     * The fixed list of public holidays. An effective registration date that lands on any of these
954	     * is rolled forward, together with weekends, to the next non-holiday business day.
955	     */
956	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
957	        LocalDate.of(2026, 1, 1),
958	        LocalDate.of(2026, 1, 26),
959	        LocalDate.of(2026, 4, 25),
960	        LocalDate.of(2026, 12, 25),
961	        LocalDate.of(2026, 12, 28));
962	
963	    private static LocalDate toBusinessDay(LocalDate date) {
964	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
965	            date = date.plusDays(1);
966	        }
967	        return date;
968	    }
969	
970	    private static boolean isWeekend(LocalDate date) {
971	        return switch (date.getDayOfWeek()) {
972	            case SATURDAY, SUNDAY -> true;
973	            default -> false;
974	        };
975	    }
