977	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
978	    @Override
979	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
980	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
981	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
982	            OwnerDto replay = idempotentCreates.get(idempotencyKey);
983	            if (replay != null) {
984	                return new ResponseEntity<>(replay, HttpStatus.OK);
985	            }
986	        }
987	        String normalizedLine1 = null;
988	        String normalizedLine2 = null;
989	        String composedAddress;
990	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
991	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
992	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
993	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
994	            }
995	            composedAddress = normalizedLine2 == null
996	                ? normalizedLine1
997	                : normalizedLine1 + " " + normalizedLine2;
998	        } else {
999	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
1000	        }
1001	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
1002	        rejectCityAtCapacity(ownerFieldsDto.getCity());
1003	        HttpHeaders headers = new HttpHeaders();
1004	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
1005	        owner.setAddress(composedAddress);
1006	        owner.setAddressLine1(normalizedLine1);
1007	        owner.setAddressLine2(normalizedLine2);
1008	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
1009	        owner.setTelephone(normalizedTelephone);
1010	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
1011	        owner.setEmail(normalizedEmail);
1012	        validatePostcode(owner.getCity(), owner.getPostcode());
1013	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
1014	        rejectDuplicateIdentity(normalizedTelephone, normalizedEmail, owner.getLastName());
1015	        rejectFutureRegistrationDate(owner.getRegistrationDate());
1016	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
1017	        LocalDate registrationDate = toBusinessDay(effectiveDate);
1018	        rejectDailyOwnerLimit(registrationDate);
1019	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
1020	        owner.setCapacityWarning(capacityWarningFor(owner.getCity()));
1021	        owner.setRegistrationDate(registrationDate);
1022	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
1023	        owner.setMemberId(deduplicateMemberId(
1024	            memberIdFor(region, owner.getRegistrationDate(), normalizedTelephone, owner.getLastName())));
1025	        owner.setHouseholdId(householdId);
1026	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
1027	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1028	        int membershipPoints = membershipPointsFor(owner);
1029	        owner.setMembershipPoints(membershipPoints);
1030	        int membershipLevel = membershipLevelForPoints(membershipPoints);
1031	        // A declared household member (sharesHousehold) keeps its point-derived level; an owner
1032	        // admitted into an existing household implicitly has its level capped one above the
1033	        // household's current maximum.
1034	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
1035	            membershipLevel = capMembershipLevelByHousehold(membershipLevel, owner.getHouseholdId());
1036	        }
1037	        owner.setMembershipLevel(membershipLevel);
1038	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone, normalizedEmail);
1039	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
1040	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
1041	        this.clinicService.saveOwner(owner);
1042	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
1043	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
1044	        emitOwnerCreatedEvent(owner);
1045	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
1046	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
1047	            idempotentCreates.put(idempotencyKey, ownerDto);
1048	        }
1049	        headers.setLocation(UriComponentsBuilder.newInstance()
1050	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
1051	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
1052	    }
1053	
1054	    /**
1055	     * Emits the immutable {@code OWNER_CREATED} structured event to the {@code AUDIT} logger as a
1056	     * JSON object {@code {seq, ownerId, memberId, membershipLevel, event}}. The {@code seq} is a
1057	     * per-application monotonically increasing integer that totally orders creates, and
1058	     * {@code memberId} carries the owner's current primary identifier
1059	     * ({@link #primaryIdentifierOf}). This is a distinct line from the human-readable audit line.
1060	     */
1061	    private void emitOwnerCreatedEvent(Owner owner) {
1062	        Map<String, Object> event = new LinkedHashMap<>();
1063	        event.put("seq", OWNER_EVENT_SEQ.incrementAndGet());
1064	        event.put("ownerId", owner.getId());
1065	        event.put("memberId", primaryIdentifierOf(owner));
1066	        event.put("membershipLevel", owner.getMembershipLevel());
1067	        event.put("event", "OWNER_CREATED");
1068	        AUDIT.info(EVENT_MAPPER.writeValueAsString(event));
1069	    }
1070	
1071	    /**
1072	     * The owner's current primary identifier carried by the {@code OWNER_CREATED} event: the unified
1073	     * {@code memberId} into which the former {@code customerCode} has been consolidated.
1074	     */
1075	    private static String primaryIdentifierOf(Owner owner) {
1076	        return owner.getMemberId();
1077	    }
